package arena

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

// SetPaused freezes posts, replies, tips, and ticket buys when on is true/1/yes.
// Pass false/0/no to reopen. Ticket sells are never paused.
func SetPaused(cur realm, on string) {
	mustAdmin(cur)
	switch on {
	case "true", "1", "yes":
		state.paused = true
	case "false", "0", "no":
		state.paused = false
	default:
		panic("paused must be true or false")
	}
	chain.Emit("ArenaPause", "paused", on, "admin", state.admin.String())
}

// SetTreasury moves future protocol fees and surplus sweeps to next.
func SetTreasury(cur realm, next address) {
	mustAdmin(cur)
	if !next.IsValid() {
		panic("bad treasury")
	}
	state.treasury = next
	chain.Emit("ArenaTreasury", "treasury", next.String())
}

// TransferAdmin rotates the pause/sweep key.
func TransferAdmin(cur realm, next address) {
	mustAdmin(cur)
	if !next.IsValid() {
		panic("bad admin")
	}
	state.admin = next
	chain.Emit("ArenaAdmin", "admin", next.String())
}

// SetSuccessor records the package path of a later realm.
// An empty path clears it. This does not move coins or shares.
func SetSuccessor(cur realm, next string) {
	mustAdmin(cur)
	next = strings.TrimSpace(next)
	if next != "" {
		if !validSuccessor(next) || next == unsafe.CurrentRealm().PkgPath() {
			panic("bad successor")
		}
	}
	state.successor = next
	chain.Emit("ArenaSuccessor", "path", next)
}

func validSuccessor(path string) bool {
	const prefix = "gno.land/r/"
	if !strings.HasPrefix(path, prefix) || len(path) > 128 {
		return false
	}
	rest := path[len(prefix):]
	if rest == "" || strings.HasSuffix(rest, "/") || strings.Contains(rest, "//") || strings.Contains(rest, ".") {
		return false
	}
	for i := 0; i < len(rest); i++ {
		c := rest[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9', c == '/', c == '_':
		default:
			return false
		}
	}
	return true
}

// Sweep sends this realm's ugnot above TotalReserve to the treasury.
// confirm must be the word "sweep". Ticket collateral is not included.
func Sweep(cur realm, confirm string) {
	mustAdmin(cur)
	if confirm != "sweep" {
		panic("confirm sweep")
	}
	if !state.treasury.IsValid() {
		panic("treasury not set")
	}
	bal := banker.NewReadonlyBanker().GetCoins(cur.Address()).AmountOf("ugnot")
	if bal < state.totalReserve {
		panic("insolvent")
	}
	surplus := bal - state.totalReserve
	payout(cur, state.treasury, surplus, "treasury")
	chain.Emit("ArenaSweep", "ugnot", strconv.FormatInt(surplus, 10))
}

package arena

import (
	"chain"
	"chain/runtime"
	"math/overflow"
	"strconv"
)

// Post publishes a top-level post and returns its id.
// gated is yes/1/true/khoa to withhold the body from Render.
// The body is still public chain state. Pass an empty gated value for a public post.
func Post(cur realm, body, gated string) int {
	who := caller(cur)
	mustNoPay()
	if state.paused {
		panic("paused")
	}
	author := mustMember(who)
	return writePost(author, 0, body, isYes(gated))
}

// Reply publishes a reply to parent and returns the new id. Replies are public.
func Reply(cur realm, parent int, body string) int {
	who := caller(cur)
	mustNoPay()
	if state.paused {
		panic("paused")
	}
	author := mustMember(who)
	target := postByID(parent)
	if target == nil {
		panic("unknown post")
	}
	if target.Deleted {
		panic("deleted")
	}
	id := writePost(author, parent, body, false)
	target.Replies++
	state.replies.Set(pad(parent)+"/"+pad(id), id)
	return id
}

func writePost(author *Profile, parent int, body string, gated bool) int {
	body = cleanBody(body)
	id := state.nextID
	state.nextID++
	p := &Article{
		ID:      id,
		Author:  author.Addr,
		Body:    body,
		Height:  runtime.ChainHeight(),
		ReplyTo: parent,
		Gated:   gated,
	}
	state.posts.Set(pad(id), p)
	if parent == 0 {
		author.Posts++
		state.feed.Set(pad(id), id)
		state.byAuthor.Set(authorKey(author.Addr, id), id)
		chain.Emit(
			"ArenaPost",
			"id", strconv.Itoa(id),
			"author", author.Addr.String(),
			"handle", author.Handle,
			"gated", yesNo(gated),
		)
	} else {
		chain.Emit(
			"ArenaReply",
			"id", strconv.Itoa(id),
			"parent", strconv.Itoa(parent),
			"author", author.Addr.String(),
			"handle", author.Handle,
		)
	}
	return id
}

func yesNo(v bool) string {
	if v {
		return "yes"
	}
	return "no"
}

// Delete soft-deletes the caller's post and clears its body from current state.
// The original transaction still holds the text in chain history.
func Delete(cur realm, id int) {
	who := caller(cur)
	mustNoPay()
	mustMember(who)
	p := postByID(id)
	if p == nil {
		panic("unknown post")
	}
	if p.Deleted {
		panic("deleted")
	}
	if p.Author != who {
		panic("author only")
	}
	if p.ReplyTo == 0 {
		state.feed.Remove(pad(id))
		state.byAuthor.Remove(authorKey(who, id))
		if author := profileByAddr(who); author != nil && author.Posts > 0 {
			author.Posts--
		}
	} else {
		state.replies.Remove(pad(p.ReplyTo) + "/" + pad(id))
		if parent := postByID(p.ReplyTo); parent != nil && parent.Replies > 0 {
			parent.Replies--
		}
	}
	p.Deleted = true
	p.Body = ""
	p.Gated = false
	chain.Emit("ArenaDelete", "id", strconv.Itoa(id), "author", who.String())
}

// Like adds the caller's like. One like per account.
func Like(cur realm, id int) {
	who := caller(cur)
	mustNoPay()
	mustMember(who)
	p := livePost(id)
	k := likeKey(id, who)
	if state.likes.Has(k) {
		panic("already liked")
	}
	state.likes.Set(k, 1)
	p.Likes++
	chain.Emit("ArenaLike", "id", strconv.Itoa(id), "from", who.String())
}

// Unlike removes the caller's like.
func Unlike(cur realm, id int) {
	who := caller(cur)
	mustNoPay()
	mustMember(who)
	p := livePost(id)
	k := likeKey(id, who)
	if !state.likes.Has(k) {
		panic("not liked")
	}
	state.likes.Remove(k)
	if p.Likes > 0 {
		p.Likes--
	}
	chain.Emit("ArenaUnlike", "id", strconv.Itoa(id), "from", who.String())
}

// Tip forwards the attached ugnot to the post's author. The realm does not keep it.
func Tip(cur realm, id int) {
	who := caller(cur)
	if state.paused {
		panic("paused")
	}
	mustMember(who)
	sent := takeUgnot(cur)
	p := livePost(id)
	author := profileByAddr(p.Author)
	if author == nil {
		panic("register first")
	}
	p.Tips = overflow.Add64p(p.Tips, sent)
	author.TipsIn = overflow.Add64p(author.TipsIn, sent)
	if self := profileByAddr(who); self != nil {
		self.TipsOut = overflow.Add64p(self.TipsOut, sent)
	}
	payout(cur, p.Author, sent, "author")
	chain.Emit(
		"ArenaTip",
		"id", strconv.Itoa(id),
		"from", who.String(),
		"to", p.Author.String(),
		"ugnot", strconv.FormatInt(sent, 10),
	)
}

// GatedBody returns a gated post's text for the author or a current ticket holder.
// Chain storage is public; this only gates the convenience call and Render.
func GatedBody(cur realm, id int) string {
	who := caller(cur)
	mustNoPay()
	mustMember(who)
	p := livePost(id)
	if !p.Gated {
		return p.Body
	}
	if p.Author != who && getShares(who, p.Author) < 1 {
		panic("need a ticket")
	}
	return p.Body
}

func livePost(id int) *Article {
	p := postByID(id)
	if p == nil {
		panic("unknown post")
	}
	if p.Deleted {
		panic("deleted")
	}
	return p
}

// Liked reports whether who liked the post.
func Liked(who address, id int) bool {
	if id <= 0 {
		return false
	}
	return state.likes.Has(likeKey(id, who))
}

package arena

import (
	"chain"
	"chain/runtime"
	"strings"
)

// Register opens a profile for the calling account.
// handle is 3–16 chars of a-z, 0-9 and underscore. referrer may be empty
// or the bech32 address of an existing member. A member can register once.
func Register(cur realm, handle, name, bio, referrer string) {
	who := caller(cur)
	mustNoPay()
	if profileByAddr(who) != nil {
		panic("already registered")
	}
	handle = strings.ToLower(strings.TrimSpace(handle))
	if !validHandle(handle) {
		panic("bad handle")
	}
	if state.byHandle.Has(handle) {
		panic("handle taken")
	}
	if name == "" {
		name = handle
	}
	name = cleanLine(name, maxNameRunes, maxNameBytes, "name", false)
	bio = cleanLine(bio, maxBioRunes, maxBioBytes, "bio", true)

	var ref address
	referrer = strings.TrimSpace(referrer)
	if referrer != "" {
		if len(referrer) > 60 {
			panic("bad referrer")
		}
		ref = address(referrer)
		if !ref.IsValid() {
			panic("bad referrer")
		}
		if ref == who {
			panic("self referral")
		}
		if profileByAddr(ref) == nil {
			panic("referrer not registered")
		}
	}

	p := &Profile{
		Addr:     who,
		Handle:   handle,
		Name:     name,
		Bio:      bio,
		Referrer: ref,
		Joined:   runtime.ChainHeight(),
	}
	state.byAddr.Set(who.String(), p)
	state.byHandle.Set(handle, p)
	state.books.Set(who.String(), &book{})
	chain.Emit(
		"ArenaRegister",
		"addr", who.String(),
		"handle", handle,
		"referrer", ref.String(),
	)
}

// UpdateProfile replaces the display name and bio. The handle stays.
func UpdateProfile(cur realm, name, bio string) {
	who := caller(cur)
	mustNoPay()
	p := mustMember(who)
	if strings.TrimSpace(name) == "" {
		name = p.Handle
	}
	p.Name = cleanLine(name, maxNameRunes, maxNameBytes, "name", false)
	p.Bio = cleanLine(bio, maxBioRunes, maxBioBytes, "bio", true)
	chain.Emit("ArenaProfile", "addr", who.String(), "handle", p.Handle)
}

// Follow records that the caller follows handle.
func Follow(cur realm, handle string) {
	who := caller(cur)
	mustNoPay()
	self := mustMember(who)
	target := lookup(handle)
	if target == nil {
		panic("unknown handle")
	}
	if target.Addr == who {
		panic("cannot follow self")
	}
	k := followKey(who, target.Addr)
	if state.follows.Has(k) {
		panic("already following")
	}
	state.follows.Set(k, 1)
	state.fans.Set(fanKey(target.Addr, who), 1)
	self.Following++
	target.Followers++
	chain.Emit("ArenaFollow", "from", who.String(), "to", target.Addr.String(), "handle", target.Handle)
}

// Unfollow removes a follow.
func Unfollow(cur realm, handle string) {
	who := caller(cur)
	mustNoPay()
	self := mustMember(who)
	target := lookup(handle)
	if target == nil {
		panic("unknown handle")
	}
	k := followKey(who, target.Addr)
	if !state.follows.Has(k) {
		panic("not following")
	}
	state.follows.Remove(k)
	state.fans.Remove(fanKey(target.Addr, who))
	if self.Following > 0 {
		self.Following--
	}
	if target.Followers > 0 {
		target.Followers--
	}
	chain.Emit("ArenaUnfollow", "from", who.String(), "to", target.Addr.String(), "handle", target.Handle)
}

// Following reports whether from follows the handle.
func Following(from address, handle string) bool {
	target := lookup(handle)
	if target == nil {
		return false
	}
	return state.follows.Has(followKey(from, target.Addr))
}

package arena

import (
	"strings"
)

// Holding is one creator's tickets in a wallet. It is a copy.
type Holding struct {
	Creator address
	Handle  string
	Amount  int
}

func mustLimit(n int) int {
	if n < 1 || n > 20 {
		panic("limit")
	}
	return n
}

// Feed lists newest top-level posts with id < before. before 0 starts at the newest.
func Feed(before, limit int) []Article {
	limit = mustLimit(limit)
	posts := recentPosts(before, limit)
	out := make([]Article, len(posts))
	for i, p := range posts {
		out[i] = *p
	}
	return out
}

// PostsBy lists one member's newest top-level posts with id < before.
func PostsBy(addr address, before, limit int) []Article {
	limit = mustLimit(limit)
	prefix := addr.String() + "/"
	out := make([]Article, 0, limit)
	state.byAuthor.ReverseIterate(prefix, prefix+"~", func(key string, value any) bool {
		id, ok := value.(int)
		if !ok {
			panic("author type")
		}
		if before > 0 && id >= before {
			return false
		}
		p := postByID(id)
		if p == nil || p.Deleted {
			return false
		}
		out = append(out, *p)
		return len(out) >= limit
	})
	return out
}

// Replies lists direct replies of parent with id > after, oldest first.
func Replies(parent, after, limit int) []Article {
	limit = mustLimit(limit)
	if parent <= 0 {
		panic("id")
	}
	prefix := pad(parent) + "/"
	start := prefix
	if after > 0 {
		start = prefix + pad(after) + "\x00"
	}
	out := make([]Article, 0, limit)
	state.replies.Iterate(start, prefix+"~", func(key string, value any) bool {
		id, ok := value.(int)
		if !ok {
			panic("reply type")
		}
		p := postByID(id)
		if p == nil || p.Deleted {
			return false
		}
		out = append(out, *p)
		return len(out) >= limit
	})
	return out
}

// Handles lists profiles in handle order, strictly after the given handle.
func Handles(after string, limit int) []Profile {
	limit = mustLimit(limit)
	start := ""
	after = strings.ToLower(strings.TrimSpace(after))
	if after != "" {
		start = after + "\x00"
	}
	out := make([]Profile, 0, limit)
	state.byHandle.Iterate(start, "", func(key string, value any) bool {
		p, ok := value.(*Profile)
		if !ok {
			panic("profile type")
		}
		out = append(out, *p)
		return len(out) >= limit
	})
	return out
}

// FollowingList lists profiles `who` follows, in address order, after `after`.
func FollowingList(who, after address, limit int) []Profile {
	return edgeList(who, after, limit, ">")
}

// FollowerList lists profiles that follow `who`, in address order, after `after`.
func FollowerList(who, after address, limit int) []Profile {
	return edgeList(who, after, limit, "<")
}

func edgeList(who, after address, limit int, sep string) []Profile {
	limit = mustLimit(limit)
	if !who.IsValid() {
		panic("bad address")
	}
	prefix := who.String() + sep
	start := prefix
	if after.IsValid() {
		start = prefix + after.String() + "\x00"
	}
	out := make([]Profile, 0, limit)
	tree := state.follows
	if sep == "<" {
		tree = state.fans
	}
	tree.Iterate(start, prefix+"~", func(key string, value any) bool {
		i := strings.LastIndex(key, sep)
		if i < 0 {
			return false
		}
		p := profileByAddr(address(key[i+1:]))
		if p == nil {
			return false
		}
		out = append(out, *p)
		return len(out) >= limit
	})
	return out
}

// Holdings lists ticket balances of holder, after the given creator address.
func Holdings(holder, after address, limit int) []Holding {
	limit = mustLimit(limit)
	if !holder.IsValid() {
		panic("bad address")
	}
	prefix := holder.String() + "/"
	start := prefix
	if after.IsValid() {
		start = prefix + after.String() + "\x00"
	}
	out := make([]Holding, 0, limit)
	state.shares.Iterate(start, prefix+"~", func(key string, value any) bool {
		n, ok := value.(int)
		if !ok {
			panic("share type")
		}
		i := strings.LastIndex(key, "/")
		if i < 0 || n < 1 {
			return false
		}
		creator := address(key[i+1:])
		handle := ""
		if p := profileByAddr(creator); p != nil {
			handle = p.Handle
		}
		out = append(out, Holding{Creator: creator, Handle: handle, Amount: n})
		return len(out) >= limit
	})
	return out
}

// Hot ranks the newest window the same way Render does. It is not a global index.
func Hot(limit int) []Article {
	limit = mustLimit(limit)
	posts := recentPosts(0, hotWindow)
	top := make([]scoredPost, 0, limit)
	for _, p := range posts {
		score := int64(p.Likes)*1_000_000 + p.Tips
		top = insertRank(top, scoredPost{p: p, score: score}, limit)
	}
	out := make([]Article, len(top))
	for i, row := range top {
		out[i] = *row.p
	}
	return out
}

// MemberCount is the number of registered handles.
func MemberCount() int { return state.byHandle.Size() }

// FeedCount is the number of live top-level posts still in the feed index.
func FeedCount() int { return state.feed.Size() }

// LatestID is the newest post id, or 0 when nothing has been posted.
func LatestID() int {
	if state.nextID <= 1 {
		return 0
	}
	return state.nextID - 1
}

const hotWindow = 30

type scoredPost struct {
	p     *Article
	score int64
}

func insertRank(top []scoredPost, row scoredPost, limit int) []scoredPost {
	if len(top) == limit && row.score <= top[len(top)-1].score {
		return top
	}
	top = append(top, row)
	for i := len(top) - 1; i > 0; i-- {
		if top[i].score <= top[i-1].score {
			break
		}
		top[i], top[i-1] = top[i-1], top[i]
	}
	if len(top) > limit {
		top = top[:limit]
	}
	return top
}

func recentPosts(before, limit int) []*Article {
	end := ""
	if before > 0 {
		end = pad(before)
	}
	out := make([]*Article, 0, limit)
	state.feed.ReverseIterate("", end, func(key string, value any) bool {
		id, ok := value.(int)
		if !ok {
			panic("feed type")
		}
		if before > 0 && id >= before {
			return false
		}
		p := postByID(id)
		if p == nil || p.Deleted || p.ReplyTo != 0 {
			return false
		}
		out = append(out, p)
		return len(out) >= limit
	})
	return out
}

package arena

import "strconv"

// Render is the short gnoweb page for this fund realm.
// The long client and Sheet live in the view realm. A realm has to declare
// Render, and the storage deposit of this package cannot hold both the curve
// and the full client.
func Render(path string) string {
	line := "# Arena\n\nPhien ban " + ProtocolVersion
	if state.successor != "" {
		line += "\n\nKe tiep: " + state.successor
	}
	if state.paused {
		line += "\n\nTam dung dang bat. Ban ve van mo."
	}
	line += "\n\nThanh vien: " + strconv.Itoa(MemberCount())
	return line
}

// Package arena is a SocialFi realm: profiles, posts, follows, GNOT tips,
// and creator tickets priced on a quadratic bonding curve.
//
// Ticket collateral sits in this realm as totalReserve. Trade fees are
// forwarded out of that collateral, and Sweep only sends coins above it.
package arena

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"unicode/utf8"

	"gno.land/p/nt/avl/v0"
)

const (
	// CreatorFeeBps is the creator's cut of each ticket trade.
	CreatorFeeBps int64 = 500
	// ProtocolFeeBps is forwarded to the treasury on each ticket trade.
	ProtocolFeeBps int64 = 500
	// ReferralFeeBps is paid to the creator's referrer when they have one.
	ReferralFeeBps int64 = 100
	// TicketUnit is the ugnot price of ticket number 1. Ticket i costs i² units.
	TicketUnit int64 = 10_000
	// MaxSupply is the most tickets one creator can have outstanding.
	MaxSupply = 2000
	// MaxTrade is the most tickets one buy or sell can move.
	MaxTrade = 20
	// MaxBodyRunes is the longest post, counted in runes.
	MaxBodyRunes = 280
	// ProtocolVersion is the immutable revision of this package.
	// A later package is announced with SetSuccessor. It does not hold this reserve.
	ProtocolVersion = "1"

	maxHandle    = 16
	minHandle    = 3
	maxNameRunes = 32
	maxNameBytes = 128
	maxBioRunes  = 160
	maxBioBytes  = 640
	maxBodyBytes = 1120
)

// Profile is a copy of a member's public record.
type Profile struct {
	Addr      address
	Handle    string
	Name      string
	Bio       string
	Referrer  address
	Joined    int64
	Posts     int
	Followers int
	Following int
	TipsIn    int64
	TipsOut   int64
}

// Article is a copy of one post. Gated bodies are still stored on chain;
// Render withholds them, and GatedBody checks the caller.
type Article struct {
	ID      int
	Author  address
	Body    string
	Height  int64
	ReplyTo int
	Likes   int
	Replies int
	Tips    int64
	Gated   bool
	Deleted bool
}

type book struct {
	Supply  int
	Reserve int64
	Holders int
}

// Trees stay unexported. avl.Iterate takes a callback; handing out the
// tree would let another realm run that callback under this realm.
type store struct {
	admin        address
	treasury     address
	paused       bool
	nextID       int
	totalReserve int64
	byAddr       *avl.Tree
	byHandle     *avl.Tree
	posts        *avl.Tree
	feed         *avl.Tree
	replies      *avl.Tree
	byAuthor     *avl.Tree
	follows      *avl.Tree
	fans         *avl.Tree
	likes        *avl.Tree
	books        *avl.Tree
	shares       *avl.Tree
	successor    string
}

var state *store

func init() {
	if CreatorFeeBps < 0 || ProtocolFeeBps < 0 || ReferralFeeBps < 0 {
		panic("fees")
	}
	if CreatorFeeBps+ProtocolFeeBps+ReferralFeeBps >= 10_000 {
		panic("fees")
	}
	state = newStore()
	deployer := unsafe.OriginCaller()
	if deployer.IsValid() {
		state.admin = deployer
		state.treasury = deployer
	}
}

func newStore() *store {
	return &store{
		nextID:   1,
		byAddr:   avl.NewTree(),
		byHandle: avl.NewTree(),
		posts:    avl.NewTree(),
		feed:     avl.NewTree(),
		replies:  avl.NewTree(),
		byAuthor: avl.NewTree(),
		follows:  avl.NewTree(),
		fans:     avl.NewTree(),
		likes:    avl.NewTree(),
		books:    avl.NewTree(),
		shares:   avl.NewTree(),
	}
}

// Admin is the address allowed to pause, sweep surplus, and rotate treasury.
func Admin() address { return state.admin }

// Treasury receives protocol fees and swept surplus.
func Treasury() address { return state.treasury }

// Version is this package revision. It has no setter.
func Version() string { return ProtocolVersion }

// Successor is the package path of a later realm, or empty.
// The later realm does not receive this realm's ticket reserve.
func Successor() string { return state.successor }

// Paused reports whether new posts, replies, tips, and ticket buys are frozen.
// Sells stay open so ticket collateral can still exit.
func Paused() bool { return state.paused }

// TotalReserve is the ugnot locked to back outstanding tickets.
func TotalReserve() int64 { return state.totalReserve }

func caller(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("direct user call only")
	}
	return cur.Previous().Address()
}

func mustNoPay() {
	if len(unsafe.OriginSend()) != 0 {
		panic("this call takes no payment")
	}
}

func takeUgnot(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("direct user call only")
	}
	coins := unsafe.OriginSend()
	if len(coins) != 1 || coins[0].Denom != "ugnot" || coins[0].Amount <= 0 {
		panic("send ugnot only")
	}
	return coins[0].Amount
}

func payout(cur realm, to address, amt int64, why string) {
	if amt == 0 {
		return
	}
	if amt < 0 || !to.IsValid() {
		panic("bad recipient: " + why)
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), to, chain.Coins{chain.NewCoin("ugnot", amt)})
}

func mustAdmin(cur realm) {
	who := caller(cur)
	mustNoPay()
	if who != state.admin {
		panic("admin only")
	}
}

func pad(n int) string {
	if n < 0 {
		panic("id")
	}
	s := strconv.Itoa(n)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func validHandle(s string) bool {
	if len(s) < minHandle || len(s) > maxHandle {
		return false
	}
	alnum := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
			alnum = true
		case c == '_':
		default:
			return false
		}
	}
	if !alnum || reserved(s) {
		return false
	}
	return true
}

func reserved(h string) bool {
	switch h {
	case "about", "people", "hot", "feed", "following", "admin", "arena", "u", "p", "t":
		return true
	default:
		return false
	}
}

func cleanLine(s string, maxRunes, maxBytes int, label string, allowEmpty bool) string {
	s = strings.TrimSpace(s)
	if s == "" {
		if allowEmpty {
			return ""
		}
		panic(label + " length")
	}
	if utf8.RuneCountInString(s) > maxRunes || len(s) > maxBytes {
		panic(label + " length")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < 0x20 || c == 0x7f || c == '<' {
			panic(label + " has markup")
		}
	}
	return s
}

func cleanBody(s string) string {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	s = strings.TrimSpace(s)
	if s == "" || utf8.RuneCountInString(s) > MaxBodyRunes || len(s) > maxBodyBytes {
		panic("body length")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\n' || c == '\t' {
			continue
		}
		if c < 0x20 || c == 0x7f || c == '<' {
			panic("body has markup")
		}
	}
	return s
}

func isYes(s string) bool {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "", "0", "no", "false", "n":
		return false
	case "1", "yes", "true", "y", "khoa":
		return true
	default:
		panic("gated must be yes or no")
	}
}

func profileByAddr(a address) *Profile {
	v := state.byAddr.Get(a.String())
	if v == nil {
		return nil
	}
	p, ok := v.(*Profile)
	if !ok {
		panic("profile type")
	}
	return p
}

func lookup(handle string) *Profile {
	h := strings.ToLower(strings.TrimSpace(handle))
	if !validHandle(h) {
		return nil
	}
	v := state.byHandle.Get(h)
	if v == nil {
		return nil
	}
	p, ok := v.(*Profile)
	if !ok {
		panic("profile type")
	}
	return p
}

func mustMember(a address) *Profile {
	p := profileByAddr(a)
	if p == nil {
		panic("register first")
	}
	return p
}

func bookOf(creator address) *book {
	v := state.books.Get(creator.String())
	if v == nil {
		panic("no book")
	}
	b, ok := v.(*book)
	if !ok {
		panic("book type")
	}
	return b
}

func postByID(id int) *Article {
	if id <= 0 {
		panic("id")
	}
	v := state.posts.Get(pad(id))
	if v == nil {
		return nil
	}
	p, ok := v.(*Article)
	if !ok {
		panic("post type")
	}
	return p
}

func shareKey(holder, creator address) string {
	return holder.String() + "/" + creator.String()
}

func getShares(holder, creator address) int {
	v := state.shares.Get(shareKey(holder, creator))
	if v == nil {
		return 0
	}
	n, ok := v.(int)
	if !ok {
		panic("share type")
	}
	return n
}

func setShares(holder, creator address, n int) {
	k := shareKey(holder, creator)
	if n == 0 {
		state.shares.Remove(k)
		return
	}
	state.shares.Set(k, n)
}

func authorKey(a address, id int) string {
	return a.String() + "/" + pad(id)
}

func followKey(from, to address) string {
	return from.String() + ">" + to.String()
}

func fanKey(creator, fan address) string {
	return creator.String() + "<" + fan.String()
}

func likeKey(id int, who address) string {
	return pad(id) + "/" + who.String()
}

// ProfileByHandle returns a copy of the profile, or false when the handle is unknown.
func ProfileByHandle(handle string) (Profile, bool) {
	p := lookup(handle)
	if p == nil {
		return Profile{}, false
	}
	return *p, true
}

// ProfileOf returns a copy of the profile bound to addr.
func ProfileOf(addr address) (Profile, bool) {
	p := profileByAddr(addr)
	if p == nil {
		return Profile{}, false
	}
	return *p, true
}

// GetPost returns a copy of the post. The copy does not alias storage.
func GetPost(id int) (Article, bool) {
	if id <= 0 {
		return Article{}, false
	}
	p := postByID(id)
	if p == nil {
		return Article{}, false
	}
	return *p, true
}

// SharesOf returns how many tickets holder has of the creator's handle.
func SharesOf(holder address, handle string) int {
	p := lookup(handle)
	if p == nil {
		panic("unknown handle")
	}
	return getShares(holder, p.Addr)
}

// SupplyOf returns tickets outstanding, ugnot locked in that curve, and holders.
func SupplyOf(handle string) (supply int, reserve int64, holders int) {
	p := lookup(handle)
	if p == nil {
		panic("unknown handle")
	}
	b := bookOf(p.Addr)
	return b.Supply, b.Reserve, b.Holders
}

package arena

import (
	"chain"
	"math/overflow"
	"strconv"
)

// QuoteBuy is the exact ugnot a buyer must attach to mint amount tickets.
// due = curve + creator fee + protocol fee + referral fee.
// curve is what stays in the reserve. Fees are paid on top and forwarded.
func QuoteBuy(handle string, amount int) (due, curve, creatorFee, protocolFee, referralFee int64) {
	p := lookup(handle)
	if p == nil {
		panic("unknown handle")
	}
	curve = curveCost(bookOf(p.Addr).Supply, amount)
	creatorFee, protocolFee, referralFee = splitFees(curve, p.Referrer.IsValid())
	due = overflow.Add64p(curve, overflow.Add64p(creatorFee, overflow.Add64p(protocolFee, referralFee)))
	return
}

// QuoteSell is what a seller receives, and the fees taken out of the curve refund.
// The reserve drops by the full curve amount, so later sells stay solvent.
func QuoteSell(handle string, amount int) (proceeds, curve, creatorFee, protocolFee, referralFee int64) {
	p := lookup(handle)
	if p == nil {
		panic("unknown handle")
	}
	b := bookOf(p.Addr)
	if amount < 1 || amount > MaxTrade {
		panic("amount")
	}
	if amount > b.Supply {
		panic("not enough tickets")
	}
	curve = curveCost(b.Supply-amount, amount)
	creatorFee, protocolFee, referralFee = splitFees(curve, p.Referrer.IsValid())
	proceeds = curve - creatorFee - protocolFee - referralFee
	if proceeds <= 0 {
		panic("proceeds")
	}
	return
}

// Buy mints amount tickets of handle. Attach exactly QuoteBuy's due in ugnot.
func Buy(cur realm, handle string, amount int) {
	who := caller(cur)
	if state.paused {
		panic("paused")
	}
	mustMember(who)
	due, curve, creatorFee, protocolFee, referralFee := QuoteBuy(handle, amount)
	sent := takeUgnot(cur)
	if sent != due {
		panic("send exactly " + strconv.FormatInt(due, 10) + "ugnot")
	}
	p := lookup(handle)
	b := bookOf(p.Addr)
	b.Supply += amount
	b.Reserve = overflow.Add64p(b.Reserve, curve)
	state.totalReserve = overflow.Add64p(state.totalReserve, curve)
	addShares(who, p.Addr, amount)
	forwardFees(cur, p, creatorFee, protocolFee, referralFee)
	chain.Emit(
		"ArenaBuy",
		"buyer", who.String(),
		"creator", p.Addr.String(),
		"handle", p.Handle,
		"amount", strconv.Itoa(amount),
		"curve", strconv.FormatInt(curve, 10),
		"due", strconv.FormatInt(due, 10),
	)
}

// Sell burns amount tickets and pays the caller from the reserve, minus fees.
// Sells stay available while the realm is paused.
func Sell(cur realm, handle string, amount int) {
	who := caller(cur)
	mustNoPay()
	mustMember(who)
	proceeds, curve, creatorFee, protocolFee, referralFee := QuoteSell(handle, amount)
	if getShares(who, lookup(handle).Addr) < amount {
		panic("not enough tickets")
	}
	p := lookup(handle)
	b := bookOf(p.Addr)
	if b.Reserve < curve || state.totalReserve < curve {
		panic("insolvent")
	}
	b.Supply -= amount
	b.Reserve = overflow.Sub64p(b.Reserve, curve)
	state.totalReserve = overflow.Sub64p(state.totalReserve, curve)
	subShares(who, p.Addr, amount)
	payout(cur, who, proceeds, "seller")
	forwardFees(cur, p, creatorFee, protocolFee, referralFee)
	chain.Emit(
		"ArenaSell",
		"seller", who.String(),
		"creator", p.Addr.String(),
		"handle", p.Handle,
		"amount", strconv.Itoa(amount),
		"curve", strconv.FormatInt(curve, 10),
		"proceeds", strconv.FormatInt(proceeds, 10),
	)
}

func forwardFees(cur realm, creator *Profile, creatorFee, protocolFee, referralFee int64) {
	if protocolFee > 0 && !state.treasury.IsValid() {
		panic("treasury not set")
	}
	payout(cur, creator.Addr, creatorFee, "creator")
	payout(cur, state.treasury, protocolFee, "treasury")
	if referralFee > 0 {
		payout(cur, creator.Referrer, referralFee, "referrer")
	}
}

func addShares(holder, creator address, n int) {
	if n < 1 {
		panic("amount")
	}
	had := getShares(holder, creator)
	setShares(holder, creator, had+n)
	if had == 0 {
		bookOf(creator).Holders++
	}
}

func subShares(holder, creator address, n int) {
	had := getShares(holder, creator)
	if n < 1 || had < n {
		panic("not enough tickets")
	}
	setShares(holder, creator, had-n)
	if had == n {
		b := bookOf(creator)
		if b.Holders > 0 {
			b.Holders--
		}
	}
}

func splitFees(curve int64, referred bool) (creator, protocol, referral int64) {
	creator = bps(curve, CreatorFeeBps)
	protocol = bps(curve, ProtocolFeeBps)
	if referred {
		referral = bps(curve, ReferralFeeBps)
	}
	return
}

func bps(amount, points int64) int64 {
	if amount == 0 || points == 0 {
		return 0
	}
	if amount < 0 || points < 0 {
		panic("fee")
	}
	return overflow.Mul64p(amount, points) / 10_000
}

// curveCost is the ugnot reserve needed to move `amount` tickets starting at supply.
// Ticket i (1-based) is priced i² * TicketUnit. The sum of squares is exact.
func curveCost(supply, amount int) int64 {
	if amount < 1 || amount > MaxTrade {
		panic("amount")
	}
	if supply < 0 {
		panic("supply")
	}
	from := int64(supply)
	to := from + int64(amount)
	if to > int64(MaxSupply) {
		panic("supply cap")
	}
	return overflow.Mul64p(sumSq(to)-sumSq(from), TicketUnit)
}

func sumSq(n int64) int64 {
	if n <= 0 {
		return 0
	}
	if n > int64(MaxSupply) {
		panic("supply cap")
	}
	// n*(n+1)*(2n+1)/6, dividing 2 and 3 out before multiplying.
	a := n
	b := n + 1
	if a%2 == 0 {
		a /= 2
	} else {
		b /= 2
	}
	c := 2*n + 1
	if a%3 == 0 {
		a /= 3
	} else if b%3 == 0 {
		b /= 3
	} else if c%3 == 0 {
		c /= 3
	} else {
		panic("sumSq")
	}
	return overflow.Mul64p(overflow.Mul64p(a, b), c)
}

package arenaview

import (
	"strconv"

	arena "gno.land/r/g10ragdr3cjqkael8rslpw4y6rlelhev4h0fswcx/arena"
)

// Render is a read-only gnoweb page. Writes go to the fund realm from the website.
func Render(path string) string {
	var b string
	b = "# Arena\n\nPhien ban " + arena.Version()
	if next := arena.Successor(); next != "" {
		b += "\n\nKe tiep: " + next
	}
	if arena.Paused() {
		b += "\n\nTam dung dang bat. Ban ve van mo."
	}
	b += "\n\nThanh vien: " + strconv.Itoa(arena.MemberCount()) + "\n\n"
	posts := arena.Feed(0, 8)
	if len(posts) == 0 {
		b += "Chua co bai.\n"
		return b
	}
	for _, p := range posts {
		h, name := namesOf(p.Author)
		b += "- #" + strconv.Itoa(p.ID) + " @" + h + " " + name + "\n"
		if !p.Gated && !p.Deleted {
			b += "  " + preview(p.Body, 160) + "\n"
		}
	}
	return b
}

package arenaview

import (
	"strconv"
	"strings"

	arena "gno.land/r/g10ragdr3cjqkael8rslpw4y6rlelhev4h0fswcx/arena"
)

const pageSize = 8

// Sheet is the stable text board the website reads.
// kind selects the page. a, b, and c are cursors or decimal limits.
// Gated bodies are left empty. The fund realm still stores them.
func Sheet(kind, a, b, c string) string {
	var body string
	switch kind {
	case "feed":
		body = sheetPosts(arena.Feed(atoiOpt(a), atoiLimit(b)), false)
	case "author":
		p, ok := arena.ProfileByHandle(a)
		if !ok {
			panic("unknown handle")
		}
		body = sheetPosts(arena.PostsBy(p.Addr, atoiOpt(b), atoiLimit(c)), false)
	case "replies":
		body = sheetPosts(arena.Replies(atoiReq(a), atoiOpt(b), atoiLimit(c)), true)
	case "post":
		body = sheetOne(atoiReq(a))
	case "people":
		body = sheetProfiles(arena.Handles(a, atoiLimit(b)))
	case "profile":
		body = sheetProfile(a)
	case "account":
		body = sheetAccount(a)
	case "hot":
		body = sheetPosts(arena.Hot(atoiLimit(a)), false)
	case "followfeed":
		body = sheetFollowFeed(a, atoiLimit(b))
	case "graph":
		body = sheetProfiles(arena.FollowingList(mustAddr(a), optAddr(b), atoiLimit(c)))
	case "fans":
		body = sheetProfiles(arena.FollowerList(mustAddr(a), optAddr(b), atoiLimit(c)))
	case "holdings":
		body = sheetHoldings(arena.Holdings(mustAddr(a), optAddr(b), atoiLimit(c)))
	case "meta":
		body = sheetMeta()
	case "quotebuy":
		due, curve, cf, pf, rf := arena.QuoteBuy(a, atoiReq(b))
		body = join5(due, curve, cf, pf, rf)
	case "quotesell":
		proceeds, curve, cf, pf, rf := arena.QuoteSell(a, atoiReq(b))
		body = join5(proceeds, curve, cf, pf, rf)
	case "shares":
		body = strconv.Itoa(arena.SharesOf(mustAddr(a), b))
	default:
		panic("kind")
	}
	return "v1\n" + body
}

func sheetPosts(posts []arena.Article, full bool) string {
	var b strings.Builder
	for i, p := range posts {
		if i > 0 {
			b.WriteString("\n")
		}
		if full {
			b.WriteString(postLine(p))
		} else {
			b.WriteString(cardLine(p))
		}
	}
	return b.String()
}

func sheetOne(id int) string {
	p, ok := arena.GetPost(id)
	if !ok {
		return ""
	}
	return postLine(p)
}

func sheetProfile(handle string) string {
	p, ok := arena.ProfileByHandle(handle)
	if !ok {
		return ""
	}
	return profileLine(p)
}

func sheetAccount(raw string) string {
	who := optAddr(raw)
	if !who.IsValid() {
		return ""
	}
	p, ok := arena.ProfileOf(who)
	if !ok {
		return ""
	}
	return profileLine(p)
}

func sheetProfiles(rows []arena.Profile) string {
	var b strings.Builder
	for i, p := range rows {
		if i > 0 {
			b.WriteString("\n")
		}
		b.WriteString(p.Handle + "\t" + esc(p.Name) + "\t" + strconv.Itoa(p.Followers) + "\t" + strconv.Itoa(p.Posts))
	}
	return b.String()
}

func sheetHoldings(rows []arena.Holding) string {
	var b strings.Builder
	for i, h := range rows {
		if i > 0 {
			b.WriteString("\n")
		}
		b.WriteString(h.Creator.String() + "\t" + esc(h.Handle) + "\t" + strconv.Itoa(h.Amount))
	}
	return b.String()
}

func sheetFollowFeed(raw string, limit int) string {
	who := mustAddr(raw)
	posts := arena.Feed(0, limit)
	var b strings.Builder
	n := 0
	for _, p := range posts {
		prof, ok := arena.ProfileOf(p.Author)
		if !ok || !arena.Following(who, prof.Handle) {
			continue
		}
		if n > 0 {
			b.WriteString("\n")
		}
		b.WriteString(cardLine(p))
		n++
	}
	return b.String()
}

func sheetMeta() string {
	paused := "0"
	if arena.Paused() {
		paused = "1"
	}
	return strings.Join([]string{
		arena.Version(),
		arena.Successor(),
		paused,
		strconv.FormatInt(arena.TotalReserve(), 10),
		arena.Admin().String(),
		arena.Treasury().String(),
		strconv.Itoa(arena.MemberCount()),
		strconv.Itoa(arena.FeedCount()),
		strconv.Itoa(arena.LatestID()),
	}, "\t")
}

func profileLine(p arena.Profile) string {
	supply, reserve, holders := arena.SupplyOf(p.Handle)
	next := "-1"
	if supply < arena.MaxSupply {
		due, _, _, _, _ := arena.QuoteBuy(p.Handle, 1)
		next = strconv.FormatInt(due, 10)
	}
	ref := ""
	if p.Referrer.IsValid() {
		ref = p.Referrer.String()
	}
	return strings.Join([]string{
		p.Handle,
		esc(p.Name),
		esc(p.Bio),
		p.Addr.String(),
		ref,
		strconv.Itoa(p.Posts),
		strconv.Itoa(p.Followers),
		strconv.Itoa(p.Following),
		strconv.FormatInt(p.TipsIn, 10),
		strconv.FormatInt(p.TipsOut, 10),
		strconv.Itoa(supply),
		strconv.FormatInt(reserve, 10),
		strconv.Itoa(holders),
		next,
	}, "\t")
}

func cardLine(p arena.Article) string {
	h, name := namesOf(p.Author)
	return strings.Join([]string{
		strconv.Itoa(p.ID),
		esc(h),
		esc(name),
		strconv.Itoa(p.Likes),
		strconv.Itoa(p.Replies),
		strconv.FormatInt(p.Tips, 10),
		bit(p.Gated),
		esc(openPreview(p)),
	}, "\t")
}

func postLine(p arena.Article) string {
	h, name := namesOf(p.Author)
	body := ""
	if !p.Gated && !p.Deleted {
		body = p.Body
	}
	return strings.Join([]string{
		strconv.Itoa(p.ID),
		p.Author.String(),
		esc(h),
		esc(name),
		strconv.Itoa(p.ReplyTo),
		strconv.Itoa(p.Likes),
		strconv.Itoa(p.Replies),
		strconv.FormatInt(p.Tips, 10),
		bit(p.Gated),
		bit(p.Deleted),
		strconv.FormatInt(p.Height, 10),
		esc(body),
	}, "\t")
}

func namesOf(a address) (handle, name string) {
	p, ok := arena.ProfileOf(a)
	if !ok {
		return a.String(), a.String()
	}
	return p.Handle, p.Name
}

func openPreview(p arena.Article) string {
	if p.Gated || p.Deleted {
		return ""
	}
	return preview(strings.ReplaceAll(p.Body, "\n", " "), 160)
}

func bit(v bool) string {
	if v {
		return "1"
	}
	return "0"
}

func esc(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "\r", "")
	s = strings.ReplaceAll(s, "\n", "\\n")
	s = strings.ReplaceAll(s, "\t", "\\t")
	return s
}

func join5(a, b, c, d, e int64) string {
	return strconv.FormatInt(a, 10) + "\t" + strconv.FormatInt(b, 10) + "\t" + strconv.FormatInt(c, 10) + "\t" + strconv.FormatInt(d, 10) + "\t" + strconv.FormatInt(e, 10)
}

func atoiOpt(s string) int {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 0 {
		panic("cursor")
	}
	return n
}

func atoiReq(s string) int {
	n := atoiOpt(s)
	if n < 1 {
		panic("id")
	}
	return n
}

func atoiLimit(s string) int {
	s = strings.TrimSpace(s)
	if s == "" {
		return pageSize
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		panic("limit")
	}
	if n < 1 || n > 20 {
		panic("limit")
	}
	return n
}

func mustAddr(s string) address {
	a := optAddr(s)
	if !a.IsValid() {
		panic("bad address")
	}
	return a
}

func optAddr(s string) address {
	s = strings.TrimSpace(s)
	if s == "" {
		return address("")
	}
	if len(s) > 60 {
		panic("bad address")
	}
	return address(s)
}

func preview(s string, n int) string {
	if len(s) <= n {
		return s
	}
	i := n
	for i > 0 && s[i]&0xC0 == 0x80 {
		i--
	}
	return s[:i] + "…"
}

// Package hollowmere is the on-chain slice of Book One, "The Three Ember Seeds" -- the
// adventure's own chain record, separate from garden/v2's pet-care record, per the
// owner's ask: "the adventure game needs chain features."
//
// Authored and tested without gnokey or any key material, per this assignment's own
// brief. Whether and when this package has actually been deployed is deliberately not
// asserted here: this comment ships on chain exactly as written the moment it is
// deployed, and a realm cannot be edited afterwards, so a "not deployed yet" sentence
// here would go permanently stale at the exact moment it stopped being true -- see
// garden/v2/gnomod.toml's own history for why this is a real failure mode, not a
// hypothetical one. Deploy status belongs in DECISIONS.md and STATUS.md, which can still
// be edited after the fact.
//
// ============================================================================
// THE HONESTY PROBLEM THIS PACKAGE EXISTS INSIDE -- READ THIS FIRST
// ============================================================================
//
// The adventure's levels run in the browser. This chain cannot watch a player solve the
// rune-rhyme puzzle, bonk the Great Mothkin three times, or do anything else Book One's
// plan describes -- it can only watch a wallet sign a transaction that ASSERTS those
// things happened. The plan itself says this plainly: "the levels run in the browser, so
// a determined cheat can poke at them" (pack-update/01-adventure-plan/book-one-plan.md,
// "Risks and decisions for Seán").
//
// So this package is commented, named and worded throughout to make that limit impossible
// to miss -- carried by the comments, the event name, the type names and Render's own
// wording, not by any single exported function's name in isolation (a player signing
// ClearChapter(1, 1) in a wallet sees that call and nothing else; the honesty framing has
// to already live in the surrounding names and docs, because there is no comment attached
// to a signing prompt):
//
//   - ClearChapter does not "verify" or "check" a clear. It records a CLAIM: this address
//     says it cleared this chapter, and the chain stamps that claim with the block's own
//     timestamp. Nothing here replays a puzzle, checks an input log, or asks the browser
//     for proof of anything. The function's own comment says so; the bare function name a
//     wallet shows does not carry this by itself.
//   - bookOneClaim, the storage type, and claims, the tree that holds it, are named for
//     what they are: a ledger of claims, not a record of verified outcomes.
//   - The emitted event is named ChapterClaimed, not ChapterCleared or ChapterVerified.
//   - Render's own wording repeats this to the one audience who will actually read it: a
//     player looking at their own public page.
//
// What this DOES genuinely give the game, worth having even though it is not refereed:
// the record is public, permanent, timestamped by the chain rather than the client,
// tied to a wallet rather than a browser's local storage, and readable by anyone without
// trusting gnotchi.com's server to tell the truth. For a cosy single-player adventure
// with nothing to win from another player's loss, that is a sound trade. See NOTES.md for
// the full writeup of why the owner's narrower ask (chapter purchase, the daily burrow,
// players' notes) is deliberately NOT built here, rather than half-built to look more
// complete than it is.
//
// ============================================================================
// SCOPE -- what this package is, and deliberately is not
// ============================================================================
//
// Built: chapter-completion claims (ClearChapter), Ember Seeds derived from those claims
// (never accepted as an input), a per-address progress read (BookOneClaim), and a public
// Render page.
//
// NOT built, on purpose, not half-built: chapter purchase (nothing is for sale here; this
// package handles no money at all, enforced the same way garden/v2 does, below), the daily
// burrow and its leaderboard (needs a dungeon generator that doesn't exist yet), and
// players' notes (stored free text on a permanent public page re-opens the hostile-name
// problem garden/garden.gno's own NOTES.md already has open, and deserves its own design
// pass rather than a rushed one here). See NOTES.md for the full reasoning on each.
//
// ============================================================================
// WHY THIS NEVER CALLS recover()
// ============================================================================
//
// This package calls no grc721 ledger, mints nothing, and has no transfer hook to protect
// -- the specific recover()-undoes-a-soulbound-guarantee trap garden/garden.gno's own
// SECURITY note documents does not literally apply here, because there is no ledger write
// to re-expose. But the underlying reason not to recover() is the same one stated above in
// different words: this package's entire credibility is "the chain only ever records a
// claim that fully passed every check in ClearChapter below." Every mutating path in this
// file validates completely BEFORE touching any stored claim (see ClearChapter's own
// comment for the exact validate-then-commit sequence), so an uncaught panic already
// guarantees the Gno/Cosmos SDK transaction boundary discards the whole failed call with
// no partial claim ever written. A recover() anywhere in this file -- even one added later
// for an unrelated reason -- could let a claim that failed a check halfway through land
// anyway, which is exactly the "the chain checked something it didn't" impression this
// package's own doc above insists it must never give. Don't add one.
package hollowmere

import (
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"chain"
	"chain/runtime/unsafe"
)

const (
	// bookOne is the only book number ClearChapter accepts today. Book One, "The Three
	// Ember Seeds", is the only book this plan has designed chapters for
	// (pack-update/01-adventure-plan/book-one-plan.md); Book Two is named only as a hook
	// ("something is drinking the moonlight, and nobody knows what yet") with no chapters,
	// tools, puzzles or prices written down anywhere this package could build against.
	bookOne = int64(1)

	// maxBook bounds ClearChapter's own book argument. Only bookOne exists today, so
	// maxBook == bookOne -- and unlike garden/v2's maxBackfillHours, this is not a
	// constant that could later be widened in place: this realm is immutable once
	// deployed, so maxBook is fixed at 1 here forever. A real Book Two would not widen
	// this constant in this file; it would be a wholly separate realm, with its own
	// gnomod.toml, its own empty claims tree, and its own bound to set -- it could not
	// read this package's unexported state even if it wanted to widen anything here. See
	// NOTES.md.
	maxBook = bookOne

	// numChaptersBookOne: Book One has exactly four chapters (The Mossy Burrow, The Sunken
	// Greenhouse, The Cogwork Mill, The Long Night) per the plan's own chapter list. Left
	// untyped so it doubles as claimedAt's array length below without a conversion.
	numChaptersBookOne = 4

	// numEmberSeedChapters: only chapters 1-3 each win back one Ember Seed. The plan's own
	// words: "Each chapter wins one back, and the last chapter brings them home" -- chapter
	// 4 (The Long Night) is the finale that reunites the three seeds already won, not a
	// fourth seed. See emberSeedsFor's own comment for how this is derived, never accepted
	// as a parameter.
	numEmberSeedChapters = 3
)

// bookOneClaim is one address's claimed progress through Book One. Named claim, not
// progress or record, on purpose: every field here is what an address SAID, timestamped
// by the chain when it said it, never something this package checked against the actual
// game. See the package doc above.
type bookOneClaim struct {
	// highestChapterClaimed is 0 until the first successful ClearChapter call for this
	// address, then the highest chapter number it has claimed -- chapters claim strictly in
	// order (see ClearChapter), so "highest" and "count of chapters claimed" are always the
	// same number for as long as this field exists.
	highestChapterClaimed int64

	// claimedAt[i] is the unix-second block timestamp (time.Now().Unix() at the moment
	// ClearChapter accepted chapter i+1's claim for this address), or 0 if chapter i+1 has
	// not been claimed yet. This is block time, the same chain-trustworthy clock
	// garden/v2's own SaveDay reads -- never a timestamp the caller supplies, because
	// unlike SaveDay (which batches a day's worth of actions and genuinely needs a
	// backfill window for a player who forgot to press Save), ClearChapter records one
	// single, discrete claim at the moment the wallet signs it. There is nothing to
	// backfill and nothing a client-supplied timestamp would buy a player that the chain's
	// own clock doesn't already give them for free.
	claimedAt [numChaptersBookOne]int64
}

var (
	// claims is this package's entire state: a ledger of claims, keyed by
	// claimKey(address, book), never by address alone. Book One is the only book accepted
	// today (see maxBook), and -- because this realm is immutable once deployed -- no
	// migration question from widening maxBook can ever arise here: a real Book Two would
	// be a different realm entirely, with its own empty tree, unable to read this
	// package's unexported state at all. Keying by (address, book) anyway costs nothing
	// (one string-concatenation helper, claimKey) and is simply tidier than keying by
	// address alone. See NOTES.md.
	claims = avl.NewTree()

	// totalClaimants: addresses with at least one accepted claim in Book One. Incremented
	// exactly once per address, the first time ClearChapter accepts any chapter for it --
	// see ClearChapter's own isNewClaimant handling.
	totalClaimants int64
)

// claimKey is the tree key for one (address, book) pair's claim.
func claimKey(addr address, book int64) string {
	return addr.String() + ":" + strconv.FormatInt(book, 10)
}

// ClearChapter records that the calling address CLAIMS to have cleared this chapter of
// this book. See the package doc above for what this is and is not: a timestamped,
// public, permanent claim, never a verified outcome.
//
// Accepts no coins (this package handles no money at all; see NOTES.md for why chapter
// purchase is out of scope entirely, not half-built). Chapters must clear in strict order,
// starting from 1, and each chapter may be claimed at most once per address -- both
// enforced by the single comparison below against highestChapterClaimed, the same way
// garden/v2 favours one invariant that closes several hostile cases over several separate
// ad hoc checks (see that file's SaveDay comment). Ember Seeds are never a parameter here
// or anywhere in this package: see emberSeedsFor for how they are derived instead.
//
// ATOMICITY: every check below runs to completion before anything is written. work is a
// plain value copy of this address's existing claim (or the zero value, if this is its
// first), taken after every validation has already passed; the only thing that happens to
// it is the two-field update at the bottom, so a panic anywhere above that point leaves
// the persisted claim -- if any -- completely untouched. This mirrors garden/v2's SaveDay
// pattern deliberately: a plain value copy, not a recover()-and-rollback. See the package
// doc for why recover() is never the right tool here either.
func ClearChapter(cur realm, book, chapter int64) {
	if !unsafe.OriginSend().IsZero() {
		panic("hollowmere: clearing a chapter accepts no coins; this realm has no banker and cannot return them")
	}

	caller := cur.Previous().Address()
	if !caller.IsValid() {
		panic("hollowmere: clearing a chapter requires a valid caller address")
	}

	if book < 1 || book > maxBook {
		panic("hollowmere: book " + strconv.FormatInt(book, 10) + " does not exist; only Book One is playable today")
	}
	if chapter < 1 || chapter > int64(numChaptersBookOne) {
		panic("hollowmere: chapter " + strconv.FormatInt(chapter, 10) + " does not exist in Book One; chapters run 1-4")
	}

	key := claimKey(caller, book)
	v := claims.Get(key)

	var existing bookOneClaim
	isNewClaimant := v == nil
	if !isNewClaimant {
		existing = *(v.(*bookOneClaim))
	}

	if chapter <= existing.highestChapterClaimed {
		panic("hollowmere: chapter " + strconv.FormatInt(chapter, 10) + " was already claimed cleared for this address")
	}
	if chapter > existing.highestChapterClaimed+1 {
		panic("hollowmere: chapters claim in order; claim chapter " +
			strconv.FormatInt(existing.highestChapterClaimed+1, 10) +
			" before claiming chapter " + strconv.FormatInt(chapter, 10))
	}

	now := time.Now().Unix()

	work := existing
	work.claimedAt[chapter-1] = now
	work.highestChapterClaimed = chapter

	claims.Set(key, &work)
	if isNewClaimant {
		totalClaimants++
	}

	chain.Emit(
		"ChapterClaimed",
		"address", caller.String(),
		"book", strconv.FormatInt(book, 10),
		"chapter", strconv.FormatInt(chapter, 10),
		"claimedAt", strconv.FormatInt(now, 10),
		"emberSeeds", strconv.FormatInt(emberSeedsFor(&work), 10),
	)
}

// emberSeedsFor derives the number of Ember Seeds this claim implies: one per chapter 1-3
// claimed cleared (chapter 4 is the finale that brings the three home, not a fourth seed --
// see numEmberSeedChapters's own comment). This is the ONLY place Ember Seeds are computed
// anywhere in this package. There is no exported function, field, or parameter anywhere in
// this file that lets a caller set, add, or otherwise assert an Ember Seed count directly
// -- it is always read off highestChapterClaimed, never written. A client cannot claim
// seeds it did not (claim to have) earned, because there is no spelling of a call into
// this package that takes a seed count as input at all.
//
// Reads highestChapterClaimed, never claimedAt: ClearChapter only ever advances both
// fields together (see its own comment), so the two cannot disagree today -- but
// highestChapterClaimed is the simpler source of truth. claimedAt uses 0 as its own
// "not yet claimed" sentinel while also being written from real block time, a dual
// representation of the same fact with a sentinel to keep straight; highestChapterClaimed
// needs neither. Capped at numEmberSeedChapters so chapter 4 (the finale, not a fourth
// seed-winning chapter) never adds a 4th.
func emberSeedsFor(c *bookOneClaim) int64 {
	n := c.highestChapterClaimed
	if n > numEmberSeedChapters {
		n = numEmberSeedChapters
	}
	return n
}

// BookOneClaim is the progress read for one address: what it has claimed in Book One, and
// the Ember Seed count derived from those claims. found is false if this address has never
// had a ClearChapter call accepted for Book One at all.
func BookOneClaim(addr address) (highestChapterClaimed, chapter1ClaimedAt, chapter2ClaimedAt, chapter3ClaimedAt, chapter4ClaimedAt, emberSeeds int64, found bool) {
	v := claims.Get(claimKey(addr, bookOne))
	if v == nil {
		return 0, 0, 0, 0, 0, 0, false
	}
	c := v.(*bookOneClaim)
	return c.highestChapterClaimed, c.claimedAt[0], c.claimedAt[1], c.claimedAt[2], c.claimedAt[3], emberSeedsFor(c), true
}

// TotalClaimants returns the number of addresses with at least one accepted chapter claim
// in Book One. Everything claims holds is already public via Render (there is no privacy
// cost to exposing it), but before this function the only way to reach this exact number
// was BookOneClaim(someKnownAddress) for one address at a time, or string-parsing the
// overview page Render("") returns. Neither lets another realm -- a future Book Two, a
// shop, a leaderboard -- enumerate or even count claimants, which is a real limitation for
// a ledger whose entire stated purpose is being publicly readable. See ClaimantsPage below
// for the enumerator this same gap needed.
func TotalClaimants() int64 {
	return totalClaimants
}

// maxClaimantsPageSize bounds a single ClaimantsPage call's own limit, so that call stays
// gas-bounded no matter how large claims grows over this realm's lifetime -- a caller
// cannot make one call's own cost scale with the whole ledger's size just by asking for a
// bigger page. Picked well above anything a real paging UI needs per page (a leaderboard
// or an admin view rendering a few dozen rows at a time) and far below a size that would
// make one call's own tree traversal unbounded.
const maxClaimantsPageSize = 100

// ClaimantsPage is the paginated enumerator claims needed to be genuinely publicly
// readable, not just publicly readable one known address at a time. It returns up to
// limit claim keys (each claimKey(address, book), i.e. "<address>:<book>") in the claims
// tree's own stable order, starting at offset -- the same (key, value) order
// claims.IterateByOffset itself walks, which never changes for a fixed tree.
//
// limit is CLAMPED to maxClaimantsPageSize rather than rejected outright, so a caller that
// asks for too much still gets a gas-bounded page back instead of an aborted call; offset
// and limit are otherwise rejected if non-positive/negative, since those are caller
// mistakes with no sane page to return.
//
// Paging with offset 0, then offset+len(returned page), ... until a page shorter than its
// own requested limit comes back, covers every claimant exactly once, in this stable
// order, with no duplicates and no gaps, for any snapshot where claims does not grow
// between calls -- see hollowmere_test.gno's own paging test, which proves this directly
// rather than assuming it from the underlying avl.Tree's own doc comment.
func ClaimantsPage(offset, limit int) []string {
	if offset < 0 {
		panic("hollowmere: offset must not be negative")
	}
	if limit <= 0 {
		panic("hollowmere: limit must be positive")
	}
	if limit > maxClaimantsPageSize {
		limit = maxClaimantsPageSize
	}

	keys := make([]string, 0, limit)
	claims.IterateByOffset(offset, limit, func(key string, value any) bool {
		keys = append(keys, key)
		return false
	})
	return keys
}

// Render gives each player a public page on gno.land. Path validated with
// address(path).IsValid() before anything derived from it is echoed back -- the same
// guard garden/v2's own Render uses, and for the same reason: an invalid path must get a
// generic refusal, never a page built out of attacker-controlled text.
func Render(path string) string {
	if path == "" {
		return ufmt.Sprintf(
			"# Hollowmere: Book One claims ledger\n\n"+
				"This page records what players **claim** to have cleared, timestamped by the "+
				"chain when they claimed it -- not what gno.land has verified. The chapters run "+
				"in the browser, so this realm has no way to check that any chapter was actually "+
				"played; see the package doc for why that is an honest trade, not an oversight.\n\n"+
				"* **Addresses with at least one chapter claimed**: %d\n",
			totalClaimants,
		)
	}

	addr := address(path)
	if !addr.IsValid() {
		return "# Hollowmere: Book One claims ledger\n\nNo claim for an invalid address.\n"
	}

	highest, c1, c2, c3, c4, seeds, found := BookOneClaim(addr)
	if !found {
		return ufmt.Sprintf("# Hollowmere: Book One claims ledger\n\nNo chapter claimed cleared yet for `%s`.\n", addr.String())
	}

	str := ufmt.Sprintf("# Hollowmere: Book One -- %s's claimed progress\n\n", addr.String())
	str += "This is a **claim**, timestamped by the chain when this wallet signed it -- not a verified record of play. See the package doc.\n\n"
	str += ufmt.Sprintf("* **Chapters claimed cleared**: %d of %d\n", highest, numChaptersBookOne)
	str += chapterLine(1, c1)
	str += chapterLine(2, c2)
	str += chapterLine(3, c3)
	str += chapterLine(4, c4)
	str += ufmt.Sprintf("* **Ember Seeds** (derived from chapters 1-3 claimed cleared; never claimable directly): %d\n", seeds)
	return str
}

func chapterLine(chapter, claimedAt int64) string {
	if claimedAt == 0 {
		return ufmt.Sprintf("* **Chapter %d**: not yet claimed\n", chapter)
	}
	return ufmt.Sprintf("* **Chapter %d**: claimed cleared at %d\n", chapter, claimedAt)
}
